`timescale 1ns/1ps
// Replay packets generated by the actual Python host API, checking the real RTL.
module tb_nocpu_host_trace;
    reg clk=0,rst_n=0,cv=0,rr=0;
    always #5 clk=~clk;
    wire cr,rv,irq;
    reg [7:0] op=0;
    reg [31:0] addr=0,data=0;
    wire [4:0] error;
    wire [31:0] result;
    npu_control_subsystem dut(.clk_i(clk),.rst_ni(rst_n),.cmd_valid_i(cv),.cmd_ready_o(cr),
        .cmd_op_i(op),.cmd_addr_i(addr),.cmd_data_i(data),.rsp_valid_o(rv),.rsp_ready_i(rr),
        .rsp_error_o(error),.rsp_data_o(result),.irq_o(irq),
        .ext_valid_o(),.ext_ready_i(1'b0),.ext_write_o(),.ext_addr_o(),.ext_data_o(),
        .ext_rsp_valid_i(1'b0),.ext_rsp_ready_o(),.ext_rsp_data_i(32'd0),.ext_rsp_error_i(5'd0));
    string path;
    integer fd,rc,commands=0;
    reg [31:0] expected,mask;
    initial begin
        if(!$value$plusargs("HOST_TRACE=%s",path))$fatal(1,"HOST_TRACE required");
        fd=$fopen(path,"r");if(!fd)$fatal(1,"host trace missing");
        repeat(5)@(negedge clk);rst_n=1;repeat(5)@(negedge clk);
        while(!$feof(fd))begin
            rc=$fscanf(fd,"%h %h %h %h %h\n",op,addr,data,mask,expected);
            if(rc!=5)$fatal(1,"malformed host trace");
            // The recorded host polls twice while busy, then experiences an
            // arbitrary communication delay before its completion query.
            if(op==1 && addr==4 && expected[3])wait(irq);
            @(negedge clk);
            cv=1;while(!cr)@(negedge clk);
            @(negedge clk);cv=0;
            while(!rv)@(negedge clk);
            if(error!==0 || (result&mask)!==(expected&mask))
                $fatal(1,"host command %0d op=%h addr=%h error=%0d got=%h expected=%h mask=%h",commands,op,addr,error,result,expected,mask);
            rr=1;@(negedge clk);rr=0;commands=commands+1;
        end
        $fclose(fd);$display("PASS nocpu Python host trace commands=%0d",commands);$finish;
    end
    initial begin #10000000;$fatal(1,"host trace timeout");end
endmodule
